/**
 * @name Unsafe struct.unpack with untrusted data
 * @description struct.unpack operations with untrusted input can cause buffer overflows
 * @kind path-problem
 * @problem.severity error
 * @id py/struct-unpack-buffer-overflow
 * @tags security
 *        external/cwe/cwe-121
 *        external/cwe/cwe-122
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module StructUnpackConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Find struct.unpack calls
    exists(API::CallNode call |
      call = API::moduleImport("struct").getMember("unpack").getACall() and
      // The second argument is the data buffer
      sink = call.getArg(1)
    )
  }
}

module StructUnpackFlow = TaintTracking::Global<StructUnpackConfig>;
import StructUnpackFlow::PathGraph

from StructUnpackFlow::PathNode source, StructUnpackFlow::PathNode sink
where StructUnpackFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Unsafe struct.unpack with untrusted data from $@.", source.getNode(), "user input"
